-- GENERATED by scripts/generate_operational_seed.py: update from IAT workbook v1-3 to v1-5 (1.9.0).
-- For a database that already ran 01-03. Safe to run again. Validated responses are left alone; a score
-- changes only where it still equals the v1-3 import. Evidence is added, never removed.
begin;
update public.assessment_cycles set notes = E'Imported from the IAT v1.1 instrument, workbook file v1-5 (6 Nov 2026: October 2026 FGD, KIIs and site visits; desk reviews 30 Oct and 6 Nov 2026). Scores are provisional until the validation workshop.\nAssessment period (from - to): October 2026: FGD, KIIs and site visits; desk reviews 30 Oct and 6 Nov 2026 (City plans, then 2021-2024 issuances).\nKey informants interviewed (names/positions): Positions only, per RA 10173. KIIs (Oct 2026): CDRRMO Chiefs of Operations, Research & Planning, and Administration sections; City Planning and Development Office; City Social Welfare and Development Office; City Administrator''s Office. Notes are kept in the lead assessor''s field notes, not in this workbook.\nFGD groups conducted: FGD with the CDRRMO Head and staff (Oct 2026), held at the CDRRM Office, which houses the OpCen and the EOC. Indicators were scored together using this IAT workbook.\nSites inspected: Done (Oct 2026): EOC; Operations and Rescue Office; Brgy. Liloan, one of the flood-prone barangays, with an established evacuation site, evacuation protocol, and camp coordination and management arrangements. Observed: a developing EOC with 24-hour duty for the City''s three priority areas (City Traffic Monitoring, Public Safety, Emergency Monitoring).\nStakeholder position: All offices consulted (CDRRMO, CPDO, CSWDO, City Administrator''s Office) share one aim: clear roles and responsibilities for each unit and accountable person, and that these are carried out. All agree that a Manual of Operations will help significantly.' where id = '8911a053-1b14-587f-b906-c0fb2adaf7f3'::uuid and notes like 'Imported from the IAT v1.1 workbook (file v1-3%';

-- 71 indicators changed between v1-3 and v1-5.
update public.responses r set gap_remarks = v.gap, recommended_action = v.action
from (values
('c17b15c8-b808-595b-a5e3-b86125a7db6f'::uuid, 'No ordinance establishing the CDRRMO as a regular department with JMC 2014-1 divisions; the EO is the only basis. (Field FGD notes formerly typed here were moved to A2.4, A2.6, A2.10 and B6.1.)', 'Draft an ordinance creating the CDRRMO as a regular department with Admin & Training, Research & Planning and Operations & Warning divisions and their functions (RA 10121 Sec. 12(c); JMC 2014-1). Attach the organogram and staffing pattern from MOO Ch.2, and cite CDP 2024-2030 PPAs 1.1.1-1.1.2 as the plan basis for the new items.'),
('012a93b7-515f-579e-b82d-b686e69e176d'::uuid, 'Workbook 2 -> 3. The FGD note that fewer than 4 CSO seats exist is contradicted by EO 2024-032A (5 CSOs, 2 private-sector seats); all RA 10121 Sec. 11 seats are named. Remaining gaps: (1) the academe seat in EO 2023-0041 (EVSU Ormoc) was dropped, and CDRRMC Res. No. 10 s.2024 (29 Nov 2024) recommending the City College of Ormoc as a regular member has no amending EO yet; (2) CSO accreditation by the SP is not shown; (3) the third private-sector seat is blank. Confirm at the workshop that EO 2024-032A is the latest issuance.', 'Issue an amending EO to EO 2024-032A adding the City College of Ormoc (CDRRMC Res. 10 s.2024) and restoring an academe seat (e.g., EVSU Ormoc), filling the 3rd private-sector seat, and citing the SP accreditation of each CSO. Keep the roster as an MOO Ch.1 annex and review it yearly.'),
('283b7870-a4bb-57b5-b913-ba65abab616f'::uuid, 'Workbook 4 -> 3 (Methodology 5.2): the documents prove meetings and resolutions in 2024-2025 but not four consecutive quarters, and a 4 needs proof of review and improvement. A different presiding officer signs almost every resolution (SP members, the DILG CLGOO, and in Nov 2024 the CDRRMO Head) and no written designation by the Chair was sighted. Restore 4 when minutes and attendance for four consecutive quarters are on file.', 'Keep the quarterly schedule (EO 2024-032A Sec. 2(d)); have the Mayor designate the presiding officer in writing when absent; file minutes, attendance and resolutions per quarter; add a standing agenda item on RA 12287 readiness and on this action plan. Use the minutes template in MOO Ch.1.'),
('33dca86b-ac84-535f-a6f3-585766be3912'::uuid, 'Workbook 4 -> 3: the secretariat role is documented and in use, but no written secretariat procedure was sighted and record-keeping lapses exist (undated resolution, reused control number, missing certifications).', 'Write the secretariat procedure (notice, agenda, quorum, minutes, resolution numbering register, certification and attestation, transmittal and SP-action tracking) into MOO Ch.1/Ch.2; correct Res. 04 s.2025 (date, control no.) and certify Res. 07-08 s.2025.'),
('b9af8f93-7828-5b7d-bf4d-9e3d2760f414'::uuid, 'Evacuation ordinance lacks procedural steps (who orders, triggers, enforcement); class-suspension rules not barangay-specific; ZO has no hazard overlay zones.', 'Amend the evacuation ordinance to add procedural statements: triggers tied to the warning-action matrix (A6.2), authority to order, assistance to PWD/elderly, livestock and pets (RA 12287 IRR Rule IV), and enforcement. Add granular (barangay/school-level) class and work suspension. In the CLUP/ZO update, add flood, landslide, storm-surge, liquefaction and tsunami overlay zones (CDRA MDA 1).'),
('5b1a42b2-d11d-535f-a8e9-c0aa9e59b0c0'::uuid, 'Assessor adjustment 4 -> 3 kept: past use is shown, but there is no stand-alone written protocol and no test/AAR. New finding: QRF resolutions do not record which declaration (local SP declaration or national/regional proclamation) authorises QRF use, and adoption of a regional proclamation (Res. 03 s.2025) is not distinguished from a local declaration. v1.1 limits this item to State of Calamity; the State of Imminent Disaster is now A1.8.', 'Write a State of Calamity protocol in MOO Ch.1: criteria (NDRRMC Memo on SoC criteria), RDANA/PDNA basis, CDRRMC recommendation, SP resolution template, post-declaration measures (price freeze, QRF use, reporting). Require every QRF resolution to cite the declaration relied on (SP resolution no. or Proclamation no. and date), and add a note on how national/regional proclamations (e.g., Proc. 920) apply to Ormoc. Validate the QRF trigger reading with the City Legal Office and COA.'),
('1d9cddd8-8636-5604-afde-e262e4c2b76d'::uuid, 'Workbook 4 -> 3: documents show DRRM in the LFC review and the CDP, but no CDC or LFC minutes were sighted showing CDRRMO participation changing a decision, which a 4 needs.', 'Keep representation; file CDC and LFC minutes that record CDRRMO input; use the LFC seat to secure the AA line (A4.6) and the EOC budget (B7.5) in the FY2028 budget call.'),
('4614955e-cace-5e8f-9e3c-dcb79cb1e1f9'::uuid, 'Assessor adjustment 4 -> 2 under the conflicting-evidence rule (take the lower). Restore if the current Plantilla of Personnel shows all JMC 2014-1 minimum positions filled.', 'Get the Plantilla of Personnel and vacancy list; compute filled/required. Request creation and funding of the 10 planned items in the FY2028 budget, prioritising Operations & Warning (24/7 OpCen) and Research & Planning (GIS).'),
('ab53dfc9-1973-50e5-87dc-c8d208d32bb6'::uuid, 'Observed 24/7 practice, but no approved White-level OpCen SOP, shift roster or handover record. The three monitoring streams (traffic, public safety, emergency) have no written split of tasks or reporting lines.', 'Write the OpCen normal-operations SOP (shifts, handover, monitoring, logbook, reporting times 6AM/6PM per RDRRMC8 Res. 12-006) as EOC Manual Ch.4/Ch.5, using the RDRRMOC SOPG 2022 forms (turn-over document, swapping form, duty composition by alert level); have it approved and keep 3 months of rosters as proof of use.'),
('9bf9db95-0edb-5da0-8eef-d3e3d892003b'::uuid, 'No TNA or competency-based training plan.', 'Run a TNA for all CDRRMO/EOC staff against the competency list (ICS, BLS/SFA, WASAR, CSSR, EOC, PDNA, GIS); produce a 3-year training plan with OCD VIII courses in MOO Ch.6.'),
('694e80ca-fd79-5b7a-8168-b48c0fc42f56'::uuid, 'Volunteer insurance basis approved (2022) but no proof a policy was bought; nothing for regular staff (insurance, hazard pay, PPE, MHPSS).', 'Adopt a responder welfare policy: group accident insurance (staff and accredited volunteers), PPE issue list, rest cycles, MHPSS referral with CHO (RA 11036). Memo 131 also requires EOC personnel welfare.'),
('4ea14592-7a60-5788-adad-55ccc1d630c5'::uuid, 'Accreditation and a partner MOA exist and are used. Gaps: signed and notarised MOA not on file; no registry, deployment or insurance rules; supervision sits with HEMS, not the EOC/IMT, so tasking during activation is unclear; ACDV mobilisation for AA (IRR Rule IV Sec. 5) not yet covered.', 'File the signed MOA; formalise the ACDV registry with accreditation, insurance and deployment rules (CDP PPA 2.7); route volunteer tasking through the EOC/IMT during activation; add AA tasks for ACDVs.'),
('a3561a08-069e-5542-9ffd-0d7ca99b62e6'::uuid, 'Workbook 4 -> 3: approval by the CDRRMC and the SP is now shown; a 4 needs a documented annual review or test, and A10.4 finds no annual M&E report. Barangay count in the plan (110) predates the 2022 merger; use 85.', 'Maintain; run and file the first annual LDRRMP review (A10.4); in the next update correct the barangay count to 85 and add RA 12287 anticipatory action PPAs.'),
('4802802d-6669-51ed-a1ae-51b54830b004'::uuid, 'Assessor adjustment 3 -> 2 kept: CDRA results are not yet carried into zoning overlays, a project screening step (C1.2) or the AIP; the CDP and LCCAP are not aligned with the 2023 CDRA or the 85-barangay count. Restore to 3 when the updated CLUP/ZO is approved with CDRA overlays and the CDP/AIP tags DRRM-CCA PPAs.', 'Use the CLUP/ZO update to adopt CDRA hazard overlays and the MDA 1-8 interventions; align the CDP 2024-2030 C.1 PPAs, the LCCAP 2019-2030 and the LDRRMP in one crosswalk; correct barangay counts to 85; tag AIP and LCCAP projects to CDRA risk-register entries (see C1.1-C1.4).'),
('4e61821a-2091-527b-9fc9-a1999f4a6b6d'::uuid, 'No CPs for other top hazards (landslide, tsunami, tropical cyclone, geothermal/industrial); untested CPs.', 'Prepare CPs for the remaining priority hazards and test each by tabletop; add AA annexes (A8.8) and pre-disaster recovery annex (A9.5).'),
('80aca07c-2c0a-5c9b-8852-391f75e17315'::uuid, 'PSCP not completed; no BIA or essential-functions list sighted.', 'Complete the PSCP using the PSCP Guidebook: essential functions, BIA, alternate site (links to B2.7), orders of succession, vital records. Exercise it once.'),
('62050213-3f6c-5c1b-ad96-ffc96cb10a76'::uuid, 'Workbook 4 -> 3: preparation, CDRRMC approval and SP adoption are shown; a 4 needs proof that the plan is reviewed against LDRRMP results (utilisation, PPA completion), which was not sighted. Validate the SP resolution for CY2026 and correct the year references in Res. 05 s.2025.', 'Maintain; obtain and file the SP resolution adopting the CY2026 plan; tag each LDRRMFIP item to an LDRRMP and CDP C.1 PPA code; add the AA line (A4.6) and the EOC operations line (B7.5) explicitly.'),
('32ad7cea-17c7-50c7-b639-631673e3aba0'::uuid, 'Routes, maps and safe zones not aligned with SOPs; pre-emptive evacuation triggers per barangay missing.', 'Produce barangay evacuation maps (routes, safe zones, ECs) for all 85 barangays, starting with the 46 critical flood barangays, and link triggers to the warning-action matrix (A6.2).'),
('e327b421-ea9c-5038-9f7f-9357f6b96c0f'::uuid, 'Workbook 4 -> 3: the review mechanism is approved (EO 2023-0085) and the FGD reports SGLG-type compliance, but proof of use (Certificates of Review, DILG transmittals) and evidence of improvement were not sighted. Drop to 2 if no certificates exist; validate the consolidated BDRRMP status matrix for 85 barangays.', 'File the Certificates of Review and DILG transmittals per barangay; maintain the 85-barangay status matrix with AA and evacuation-map columns; update EO 2023-0085 membership to EO 2024-032A offices.'),
('e1800441-4564-5a86-9813-92c3d72de086'::uuid, 'Workbook 4 -> 3: the 5% LDRRMF is set and approved. Res. 05 s.2025 computes it on the NTA only; RA 10121 Sec. 21 sets it at not less than 5% of estimated revenue from regular sources (NTA plus local regular revenue). Confirm the base with the Budget Office.', 'Have the Budget Office show the computation on estimated revenue from regular sources (NTA and local sources) and keep it with the budget; correct the base if only the NTA was used.'),
('51b90def-3147-54ab-a71a-97b0e033d117'::uuid, 'Workbook 4 -> 3: the 70/30 split is documented and applied; validate against the appropriation ordinance. No AA sub-allocation inside the 70% yet (A4.6).', 'Maintain the 70/30 split; show the AA sub-allocation inside the 70% (A4.6).'),
('cbee3855-118c-52f2-8301-83cd669c6703'::uuid, 'Workbook 4 -> 3: the Special Trust Fund is in use with CDRRMC and SP approval; no ledger ageing the balances by year of origin was sighted, so 5-year use cannot be shown.', 'Keep an STF ledger by year of origin showing the 5-year deadline per balance; list STF balances as an AA fund source (A4.6).'),
('2e056aca-2637-522c-91b6-069aa6e1a801'::uuid, 'Workbook 3 -> 2: utilisation is below the 80% target (FGD) and the Trust Fund balances confirm it; no quarterly utilisation report or monitoring record was sighted.', 'Track LDRRMF and Trust Fund utilisation quarterly in the CDRRMC meeting using a standard report; flag PPAs at risk by Q3; programme aged Trust Fund balances first.'),
('88c9dbde-603a-5b23-a4cd-4882ef0fb4e6'::uuid, 'No AA line, no disbursement guidance.', 'Put an AA line (up to 10% of the 70% LDRRMF) in the FY2028 LDRRMFIP under CDP PPA 3.15; map other sources (STF, donations under SP Res. 2024-102, ODA); write Budget/Accounting/BAC steps for immediate disbursement with the 30%/70% tranche rule. Revisit when DBM-COA guidelines issue.'),
('7114b994-82b1-5ed5-9135-499924a1cbc2'::uuid, 'Validate GSIS coverage of public assets and PSF proposals; CDRA shows low insurance coverage of critical facilities and none for lifelines.', 'Check that the EOC, ECs and city-owned critical facilities are on the GSIS indemnity schedule; use the CDRA facility list to set coverage priorities.'),
('cc6fb7f3-7e53-51af-9daa-122c2e3b7c51'::uuid, 'Barangay-scale coverage to validate.', 'Maintain; publish barangay hazard maps through the shared source (A5.7).'),
('3c7cd8e5-365c-5250-9266-88d8a9d27ab6'::uuid, 'No earthquake, liquefaction or tsunami DRA; climate-projection tables still labelled ''Municipality of Naval, Province of Biliran'' (template error); SP adoption and use in plans to validate.', 'Use the CDRA TWG (EO 2023-0025) to add earthquake, liquefaction and tsunami DRA, correct the Naval/Biliran table labels and re-base the CDRA on 85 barangays; adopt the CDRA with the CLUP update and set its update cycle (A5.9); cover exposure of critical facilities (A5.8) and non-asset losses (C1.3).'),
('96b50559-910e-5edd-a199-8c843d7301eb'::uuid, 'GIS capacity in R&P not confirmed.', 'Confirm GIS staff and software; train at least 2 R&P staff.'),
('2b9e564b-b2b7-5759-a5a3-bfe6c66b5e39'::uuid, 'Workbook 1 -> 2: an approved update cycle exists for the CDRA, databases and maps, but its 5-year upper bound exceeds the 3-year standard for hazard data, and no annual or 18-month cycle is set for exposure, vulnerability and critical facilities.', 'Adopt the full cycle in MOO Ch.7 and an amending EO: hazard data <=3 years; exposure, vulnerability and critical facilities <=18 months; event-triggered updates after major disasters.'),
('2137e00a-8b2c-5fa2-919c-6564fa36fbb9'::uuid, 'Tech-based gauges/sensors need re-establishing (Anilao/Malbasag).', 'Restore and insure the flood/rain gauges; set a monthly functionality check; write an EWS SOP (planned PPA).'),
('9ac83d4c-1e6f-57da-bce8-845b46b7796e'::uuid, 'Matrix does not yet link alert levels to SID request and AA (RA 12287).', 'Write the warning-action matrix (PAGASA/PHIVOLCS levels -> pre-emptive evacuation, class/work suspension, EOC level, SID request), built to take NDRRMC impact-based triggers when issued.'),
('37a945ad-cb5c-5880-9c28-fa9e629ec523'::uuid, 'No approved risk communication plan.', 'Designate the PIO and write the risk communication plan, including rumour management.'),
('38954d31-1f20-5a43-b8ab-2080a52c5dfd'::uuid, 'ECs do not yet meet RA 12076 standards.', 'Audit ECs against RA 12076/DSWD standards; prioritise retrofits for the 46 critical flood barangays.'),
('9dc1ffab-e2d5-5a17-aa0c-9b8337e7cd26'::uuid, '[Workbook score 4; imported as 3 because no test, exercise or after-action review is on record (a 4 needs one). Restore it once the evidence is attached.] Validate warehouse inventory and replenishment triggers; the 4 rests on the FGD. If no inventory with triggers is sighted at the workshop, rate 3 (use shown by Res. 06 s.2025) or lower.', 'Maintain; add AA prepositioning triggers.'),
('10e6af20-126c-54e6-9022-125426cc9fa0'::uuid, 'Sector representatives'' confirmation (FGD) not yet gathered.', 'Hold a short FGD with PWD, senior, women and youth representatives to confirm engagement.'),
('d9d7806b-ffbb-567c-98c0-e7fb057f8a88'::uuid, 'Validate joint drills with schools and hospitals.', 'Maintain; include schools and hospitals in the next CP tabletop.'),
('f957b0fc-b812-5e34-9a27-342f30f56922'::uuid, 'Workbook 1 -> 2: ICS is adopted by CDRRMC resolution, but there is no EO, IMT roster or list of pre-designated Incident Commanders, and no record of ICS use in an event.', 'Issue a Mayor''s EO implementing CDRRMC Res. 09 s.2024: pre-designated Incident Commanders by hazard and event type, IMT roster (2 deep), delegation of authority form, and the EOC-IMT interface (B6.1); complete ICS training (A2.6) and record ICS use in the next activation.'),
('0fa90af3-ab44-5839-91be-b68ea704aad4'::uuid, 'Cluster capability not assessed.', 'Assess cluster capability and adopt a cluster EO aligned to the national response clusters (RDRRMOC SOPG 2022, Table 6: 11 clusters), naming lead and member offices.'),
('8a64d65d-181f-5c3a-af70-ee88f8850e6f'::uuid, 'MDM protocol is COVID-19 only (2021); no all-hazards MDM or RDANA team designated or trained.', 'Designate MDM and RDANA teams by EO and train them.'),
('4fa4d322-826b-56f4-b035-bb48d48d24e2'::uuid, 'No pre-disaster recovery framework.', 'Use the OCD/World Bank Ready to Rebuild workbook to prepare a pre-disaster recovery framework.'),
('5b252962-c5ba-5b3c-a5a8-a493b600a9a0'::uuid, 'No mutual aid MOAs.', 'Reframe as technical mutual-aid MOAs with Kananga, Albuera, Merida, Isabel and the Province; join the Leyte DRRMCs Telecom and Response Network (planned PPA).'),
('7ee40260-e492-57cb-bc61-911289ee9ea8'::uuid, 'Workbook 4 -> 3: partnerships are documented and in use; a 4 needs annual review of partner MOAs with recorded improvements, which was not sighted. The CPR-RIMT MOA copy is unsigned; no faith-based partner instrument was in the set.', 'Keep a partner register (instrument, date, term, focal person, review date); review MOAs yearly at a CDRRMC meeting; file signed copies; add AA roles and resource commitments (B6.6) to partner MOAs.'),
('b0dde175-d7f2-5cca-a7ff-bf06c2aac1cb'::uuid, 'Design is approved, but no annual RBME report or baseline database was sighted.', 'Produce the first annual RBME report (Form 5D) and baseline database; present it to the CDRRMC and LDC; include the IAT results and the CDRA monitoring indicators (CDRA 6.7.1).'),
('5be8e243-5d21-5eeb-a3c6-865733405b24'::uuid, 'Provisional: action plans on remaining gaps not sighted.', 'Keep participating; track gaps from GKS/SGLG results.'),
('cc061ec2-0145-591c-9cca-6d70c4a9e58f'::uuid, 'Changes from learning not documented.', 'Document changes adopted from exchanges.'),
('67a69792-0f29-54e6-b586-e5c9de268741'::uuid, 'Provisional. No EO defining the EOC mandate and its relation to the CDRRMC and ICS. The CDP treats the OpCen and the EOC as separate programmes; their relationship (OpCen at White, EOC on Blue/Red activation) is not defined in any issuance.', 'Issue an EO establishing the City EOC per NDRRMC Memo 131 s.2018: the 24/7 OpCen (CDP programme 2.10) becomes the EOC on activation (CDP programme 3.3); the EOC links clusters (resource providers) and the IMT (resource user) under CDRRMC Res. 09 s.2024; the EOC is not co-located with the ICP.'),
('962ee543-8c2e-5526-b7fb-545f03d184f1'::uuid, 'Activation SOP is in use (lead assessor score 3). To keep this score under Methodology 5.2, file in the Document Vault: the activation SOP with its approval (CDRRMO Head or CDRRMC) and one activation record. Still to write: hazard-based triggers and the EOC posture under a State of Imminent Disaster (EOC Manual).', 'Write the activation matrix using NDRRMC Memo 131 s.2018 triggers (9.2.1) and standard alert codes, with the SID posture (IRR Rule IV Sec. 1). Use the RDRRMOC SOPG 2022 alert model (White/Blue/Red; Standby/Alpha/Bravo/Charlie protocols) as the template.'),
('40ceca04-5ca2-5e21-91f5-820d960a5a59'::uuid, 'ConOps is being drafted under the MOO/EOC Manual work; no approved ConOps yet. Score rises to 3 once the chapter is approved and used in an activation.', 'Write the ConOps in EOC Manual Ch.2 around the five NDRRMC Memo 131 s.2018 functions: Management, Operations, Planning, Logistics, Finance/Admin.'),
('21222890-22c7-5521-a159-2b30898d676e'::uuid, 'Compliant. To keep this score under Methodology 5.2, file in the Document Vault: the KML file and the overlay result (maps used, source and date). Alternate EOC site not yet assessed.', 'Overlay the primary and alternate EOC sites on CDRA/GeoRiskPH flood, landslide, storm-surge, liquefaction and tsunami maps; record results on the Site Selection and Mitigation sheets of the OCD EOC Capability Assessment Checklist; if a site is in a high-hazard zone, record mitigation (elevated floor, relocation trigger).'),
('36bed9fd-238f-5c18-8e2a-ec505837bf6e'::uuid, 'To keep this score under Methodology 5.2, file in the Document Vault: a copy of the document sighted (type, number, date, issuing office). Confirm whether it covers seismic design (NSCP) given Philippine Fault proximity.', 'Ask the Building Official for a structural and seismic assessment of the EOC building (NBCP, NSCP) and its occupancy certificate; record results on the Building Design sheet of the EOC Capability Checklist; schedule retrofit if needed (see C2.1).'),
('9f5775db-53b3-5711-8805-8f5ba837f7cf'::uuid, 'To keep this score under Methodology 5.2, file in the Document Vault: the generator rating (kVA), the latest test log and the fuel record. Record which of these were sighted.', 'Inventory the generator (kVA) and UPS; test the generator at full load monthly with a log; keep 72-hour fuel on site and a fuel supply contract for longer events (EOC Checklist, SOP and Supplies sheets).'),
('4f32ceb3-ecb8-504e-86ad-b7ce5cc23e0a'::uuid, 'To keep this score under Methodology 5.2, file in the Document Vault: the floor plan, checked against the Room Design sheet of the EOC Capability Checklist (operations floor, decision room, comms room, rest and sanitation).', 'Draw the EOC floor plan and check it against the Room Design and Personnel Space sheets of the EOC Capability Checklist (operations room, comms room, briefing room, rest, food, sanitation); list fixes in an EOC Manual annex.'),
('ce33fa85-d26f-5baf-a9b6-bda1997fa2dc'::uuid, 'Partial (lead assessor score 2): no 72-hour stock record of water, food and sanitation supplies for the EOC roster.', 'Stock and log 72-hour water, food, hygiene and medical supplies for the full activated EOC roster; check them quarterly with the warehouse inventory (A7.5).'),
('b71cc677-72e7-52e9-91e5-f679d8c8055c'::uuid, 'CHECK: score 3 entered, but the evidence still says no access rule, ID system or visitor log was sighted. Record what was observed (IDs, visitor log, CCTV at entrances) and file it, or set the score back to 2.', 'Write access rules in the EOC Manual: staff IDs, visitor log, badges for agency liaisons, restricted areas (comms, servers); add CCTV at entrances when the OpCen CCTV system is procured.'),
('d2ae6ad4-75bf-5d44-908e-873837d4dacb'::uuid, 'CHECK: score 3 entered, but the evidence still says fewer than 3 independent channels were proven and HF/satellite was not confirmed. Record the three channels observed and the latest radio-check log, or set the score back to 2.', 'Inventory comms and test at least 3 independent channels (VHF, HF or satellite, landline/mobile); log a weekly radio check (RDRRMC8 practice: HF Tue/Fri, VHF Wed/Fri).'),
('e3afacc1-c08f-5ac2-89ca-41966fddf92e'::uuid, 'Partial (lead assessor score 2): no second ISP, satellite link or failover test record sighted.', 'Contract a second ISP or satellite terminal on a separate path; test failover quarterly; keep offline copies of forms and contact lists (the DRRM platform works offline).'),
('a230adb8-4ecd-5529-925b-217ac6ab5ea4'::uuid, 'Provisional. Roster and handover protocol not sighted.', 'Adopt a shift handover form based on the RDRRMOC SOPG 2022 turn-over document and swapping form; keep rosters and signed handovers as proof of use.'),
('1fe91271-0036-5004-8551-65fc8070bbcc'::uuid, 'Provisional. ICS-EOC interface not defined.', 'Define the interface per NDRRMC Memo 131 s.2018 in the ICS EO (A8.1): the EOC supports the IC; clusters and partners (incl. HEMS-supervised volunteers) provide resources through the EOC; no command from the EOC.'),
('51012494-7f0c-58e7-95a1-1108515544f2'::uuid, 'Provisional. The legal authority to accept calamity donations exists (SP Res. 2024-102), but no SOP for receiving, recording, storing, distributing and reporting donations, or for registering spontaneous volunteers, was sighted. Correct the file name in the Vault (2024-1027 vs 2024-102).', 'Write the donations and volunteer SOP under SP Res. 2024-102: intake desk, deed of donation, logging, warehousing with CSWD/CGSO, distribution records, FDP posting; spontaneous-volunteer registration and tasking through the EOC.'),
('f27754e4-1e4a-5073-8a60-ad336eb3f297'::uuid, 'Validate utilisation reports.', 'Keep the line in each LDRRMFIP.'),
('ff9acfdf-8a70-5f66-a587-b852fbb9b715'::uuid, 'Provisional. Scenarios not defined; CLUP not yet updated with CDRA results. CPDO KII held Oct 2026; findings to be entered.', 'Define most-probable and most-severe scenarios per priority hazard from the CDRA and GeoRiskPH; use them to set CDP/CLUP priorities and the siting of major investments in the CLUP update (CDRA MDA 1).'),
('00ac2029-df8a-5b3b-bf2a-a329ea9c74cc'::uuid, 'Provisional: DRRM input to LDC/LFC is informal; no screening step. CPDO KII held Oct 2026 (findings to be entered); Budget KII pending.', 'Add a one-page DRR/CCA screening form to LDC/LFC project review (hazard overlay, exposure, design standard, climate expenditure tag), owned by CPDO with CDRRMO sign-off.'),
('e8ab7e23-6b6f-54e5-9ce3-11546011ebea'::uuid, 'Jobs and income losses, ecosystem service losses and cultural heritage (CLUP Heritage Overlay Zone) are not quantified. Desk-review cap of 2.', 'In the CDRA update, estimate jobs and income lost, displacement days, ecosystem services and heritage assets in the Heritage Overlay Zone; use the 10-Yr Plan business data (establishments, employment) as the baseline.'),
('1ccc93c6-a8b5-5701-9c55-497a0687abc6'::uuid, 'Provisional: a desk vulnerability scoring exists, but no engineering assessment or rapid pre-impact inspection.', 'Have the Building Official assess the EOC, ECs and critical public facilities, starting with those rated ''Poor'' in the CDRA; write a rapid pre-impact inspection checklist used at the PDRA stage.'),
('cd3c087e-ac5b-5aa6-bf83-eee0121a92a4'::uuid, 'Power arrangement made event by event (2021); no standing restoration-priority agreements with power, water and telecom providers.', 'Sign restoration-priority arrangements with power, water and telecom providers.'),
('31ccda55-5294-5294-bdf3-daa5fc4f1e84'::uuid, 'Protective ecosystems are identified in plans but not monitored as risk-reduction assets. Desk-review cap of 2.', 'Complete the watershed study; monitor forest cover in the upper Anilao-Malbasag watershed and mangrove area each year and report it to the CDRRMC (CDRA MDA 3 and 5).'),
('b7abd85d-a44b-5e48-8305-6e4e2cb57d52'::uuid, 'Provisional.', 'Write the declogging and debris protocol.'),
('e9779a68-4888-59ba-9576-f3bbd3e1344e'::uuid, 'Provisional.', 'Prepare the health AA plan with CHO and hospitals.'),
('8f86dd62-3f71-5976-bb5a-63abb9717e11'::uuid, 'Provisional desk score pending DepEd KII.', 'Ask DepEd SDO Ormoc for school contingency/AA plans and learning-continuity modalities; agree triggers for class suspension and school use as ECs (link A1.5, A6.2).'),
('9a85561d-7e4b-53a9-bab4-a8799238c305'::uuid, 'Workbook 1 -> 2: a slow-onset (El Nino) task force exists by EO with agriculture in the lead, but its plan was not sighted and there are still no early action guidelines for typhoon or flood impacts on farms, fisheries and livestock. CAO/CVO KII pending.', 'With CAO and CVO, draft agri-fisheries early action guidelines (early harvest advisories, seed and input prepositioning, livestock evacuation, animal health) using RSBSA/FishR lists and the CDRA high-risk production areas; file the El Nino Task Force plan (EO 2023-0042) as the drought chapter.'),
('65eaff76-960d-5c38-9ed9-a15cd45c5cd0'::uuid, 'Provisional: outreach not yet started; Chamber KII pending.', 'Run BCP outreach with the Chamber using CDRA hazard scenarios; track the number of MSMEs with BCPs as the 10-Yr Plan indicator.')
) as v(id, gap, action)
where r.id = v.id and r.status <> 'validated';

insert into public.evidence (id, response_id, kind, strength, title, source, note) values
('a179ab67-a47b-5649-80b6-4dee3aa45feb'::uuid, 'c17b15c8-b808-595b-a5e3-b86125a7db6f'::uuid, 'document', 'partial'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(doc review 6 Nov 2026) none of the 23 City issuances creates the CDRRMO as a regular department. CDP 2024-2030 Vol. 2 Table 17 PPAs 1.1.1-1.1.2 commit to creating regular positions for the CDRRMO complement, an Admin Officer and a Property Custodian; SP Res. 2023-347 records the CDRRMO''s "lack of manpower for emergency and disaster response".'),
('248bd590-b2b5-5415-a446-39723b557e58'::uuid, '012a93b7-515f-579e-b82d-b686e69e176d'::uuid, 'document', 'approved_in_use'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(doc review 6 Nov 2026) EO No. 2024-032A (July 2024, reviewed by City Legal 1 Jul 2024) reorganises the CDRRMC and supersedes EO 2023-0041 (16 May 2023). It lists the Mayor (chair), Vice Mayor, SP committee chairs on CCA-DRRM and public safety, Liga president, City Administrator, CDRRMO, CPDO, Budget, Accountant, CHO, CSWD, Agriculture, Engineering, Waterworks, Veterinary, CGSO, ENRO, IPGDO (GAD), DOH-CHD HEMS, DILG, DepEd SDO, DPWH, PA 802nd Bde, 8RCDG ARESCOM, PNP, BFP, PCG, PN reserve, PPA, PRC, 5 CSOs and 2 private-sector seats (EDC Leyte Geothermal, LEYECO V; a 3rd seat is blank). Proof of use: 2024-2025 CDRRMC resolutions are moved and seconded by member offices (DepEd, PNP, PCG, CSWD, Waterworks, CGSO, Engineering, CHO, a CSO). [Imported at "approved and in use" from the assessor''s score. Attach the document and proof of use, or lower the strength, at validation.]'),
('d730dbab-2490-540b-8536-2ea24553004c'::uuid, '283b7870-a4bb-57b5-b913-ba65abab616f'::uuid, 'document', 'approved_in_use'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(doc review 6 Nov 2026) resolutions sighted from the 4th Quarter meeting of 29 Nov 2024 (Res. 09, 10 s.2024), the 2nd Quarter meeting of 26 Jun 2025 (Res. 01-03 s.2025), a 3rd Quarter special meeting of 30 Sep 2025 (Res. 05), a special meeting of 8 Nov 2025 for Typhoon Tino (Res. 06) and a meeting of 20 Nov 2025 (Res. 07, 08). Res. 04 s.2025 is undated ("this __ day of November 2025") and repeats control no. 2025-07-180. EO 2024-032A Sec. 2(d) sets the quarterly schedule. No minutes or attendance sheets, and no 1st Quarter 2025 record, were in the set. [Imported at "approved and in use" from the assessor''s score. Attach the document and proof of use, or lower the strength, at validation.]'),
('94b4e181-e00c-5aba-94e9-29ea3bf59f36'::uuid, '33dca86b-ac84-535f-a6f3-585766be3912'::uuid, 'document', 'approved_in_use'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(doc review 6 Nov 2026) the CDRRMO Head certifies CDRRMC Res. 01-06 s.2025 as Secretariat; the resolutions follow one excerpt-of-minutes format with CDRRMO control numbers (e.g., CDRRMO-2025-07-178) and transmittal lists to the SP, Budget, Accounting, CPDO, DILG and OCD VIII. Lapses: Res. 04 s.2025 undated and with a reused control number; Res. 07 and 08 s.2025 carry no Secretariat certification; Res. 05 has no series year in its number. [Imported at "approved and in use" from the assessor''s score. Attach the document and proof of use, or lower the strength, at validation.]'),
('7d0b6a13-0b06-5c5e-b081-15c98487d3d4'::uuid, 'b9af8f93-7828-5b7d-bf4d-9e3d2760f414'::uuid, 'document', 'approved_in_use'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(issuances 2021-2024, read 6 Nov 2026) CDRRMC Res. 09 s.2021 (15 Dec 2021, Odette) directed all barangays to start pre-emptive evacuation of high-risk residents; Res. 08 s.2021 (Odette) and Res. 06 s.2022 (TD Agaton, 13 Apr 2022, citing DepEd Order 66 s.2012) suspended work and classes. These show the council uses the evacuation and suspension rules, event by event. [Imported at "approved and in use" from the assessor''s score. Attach the document and proof of use, or lower the strength, at validation.]'),
('faabdfb7-7561-5c71-ae35-4ecb49253d21'::uuid, '5b1a42b2-d11d-535f-a8e9-c0aa9e59b0c0'::uuid, 'document', 'approved_in_use'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(doc review 6 Nov 2026) CDRRMC Res. 03 s.2025 (26 Jun 2025) adopts Presidential Proclamation No. 920 (State of Calamity, Region VIII, San Juanico Bridge) and cites the LDRRMF; Res. 01 s.2025 cites the same regional declaration. Res. 06 s.2025 (8 Nov 2025) approves PHP 2.0 M from the 30% QRF for Typhoon Tino (Kalmaegi) relief but does not cite the declaration it relies on, although Res. 05 s.2025 states the QRF is "only utilized upon declaration of a state of calamity". CDP 2024-2030 PPA 3.1.1 lists "Declaration of State of Calamity" under the QRF programme. [Imported at "approved and in use" from the assessor''s score. Attach the document and proof of use, or lower the strength, at validation.]'),
('31b34d97-ddcd-5429-8822-dbcf7cc15ed0'::uuid, '5b1a42b2-d11d-535f-a8e9-c0aa9e59b0c0'::uuid, 'document', 'approved_in_use'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(issuances 2021-2024, read 6 Nov 2026) SP Res. 2021-366 adopted the State of Calamity for Typhoon Odette (16 Dec 2021); CDRRMC Res. 06 s.2024 recommended a State of Calamity for the dengue outbreak, capped at one year and liftable on the council''s recommendation, with CHD tasks. Two more cases of the protocol in use; still no written stand-alone protocol. [Imported at "approved and in use" from the assessor''s score. Attach the document and proof of use, or lower the strength, at validation.]'),
('22e5f598-ffec-5314-8787-0580fcae4812'::uuid, '1d9cddd8-8636-5604-afde-e262e4c2b76d'::uuid, 'document', 'approved_in_use'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(doc review 6 Nov 2026) SP Res. 2024-088 (19 Mar 2024) records that the Trust Fund-LDRRMF 2024 Budget Program and Investment Plan went through a budget plan review by CPDO, the City Budget Office and the City Accountant (LFC member offices) before SP adoption; CDP 2024-2030 Vol. 2 Sec. C.1 carries a full CCA-DRRM sub-sector with 5 programmes, showing DRRM input into the CDC plan. EO 2024-032A Sec. 2(b) tasks the CDRRMC to integrate DRR-CCA into development plans and budgets. [Imported at "approved and in use" from the assessor''s score. Attach the document and proof of use, or lower the strength, at validation.]'),
('849e1a08-3daf-56a5-9e53-8a19060a15ce'::uuid, '4614955e-cace-5e8f-9e3c-dcb79cb1e1f9'::uuid, 'document', 'partial'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(doc review 6 Nov 2026) CDP 2024-2030 PPAs 1.1.1-1.1.2 (create regular positions for the CDRRMO complement; fill Admin Officer and Property Custodian), 1.2.4, 1.6.2 and 1.15.4 (regular positions for EWS, structural assessment and CDRA database) and 2.1.3 (risk communications) confirm that the posts are still to be created. SP Res. 2023-347 records the CDRRMO''s lack of response manpower.'),
('5c55dad0-f090-5f54-9d46-2c950c6bbbcd'::uuid, 'ab53dfc9-1973-50e5-87dc-c8d208d32bb6'::uuid, 'document', 'partial'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(doc review 6 Nov 2026) CDP 2024-2030 PPA 2.10.3 "Formulation of Operations Center SOP/Manual" (programme 2.10 Ormoc City DRRM Operations Center) confirms the SOP is still to be written; strategy 2 plans an Ormoc City Integrated Operation Center and Emergency Hotline.'),
('1869308b-aea7-5ebe-ba37-ea6e10dfc0f0'::uuid, 'ab53dfc9-1973-50e5-87dc-c8d208d32bb6'::uuid, 'observation', 'partial'::public.evidence_strength, 'Site observation, October 2026', 'Assessment team site visit', '(Oct 2026 site visit) 24-hour duty is in operation at the CDRRM Office for the City''s three priority areas: City Traffic Monitoring, Public Safety and Emergency Monitoring. Score 1 -> 2: the practice is observed, but there is no approved normal-operations SOP or signed roster (a 3 needs both).'),
('cdd6ba00-f2e4-598e-a2e7-f9fede9360cc'::uuid, '9bf9db95-0edb-5da0-8eef-d3e3d892003b'::uuid, 'document', 'partial'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(doc review 6 Nov 2026) CDRRMC Res. 09 s.2024 directs the CDRRMO to train city and barangay officials and responders on ICS; CDP 2024-2030 PPAs 1.1.6 (standard training modules) and 2.6.1-2.6.3 (capacity building for CDRRMC agencies and BDRRMCs, local pool of trainers, simulation exercises). Still no TNA.'),
('bf3b9aae-43db-5ff9-935c-0415ecf0b021'::uuid, '694e80ca-fd79-5b7a-8168-b48c0fc42f56'::uuid, 'document', 'partial'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(issuances 2021-2024, read 6 Nov 2026) CDRRMC Res. 03 and 04 s.2022 (31 Mar 2022) adopt NDRRMC MC 64 s.2021 on accreditation, mobilisation and protection of community disaster volunteers, and approve a risk categorisation as the basis for buying insurance for accredited volunteers. Score 1 -> 2: an approved basis exists for volunteer insurance; no policy, staff insurance, hazard pay, PPE issue list or MHPSS arrangement was sighted.'),
('1d4d51f8-f0de-5933-9e28-23bf38b10895'::uuid, '4ea14592-7a60-5788-adad-55ccc1d630c5'::uuid, 'document', 'approved_in_use'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(doc review 6 Nov 2026) SP Res. 2023-347 (29 Dec 2023) authorises the MOA with CPR-RIMT Rapid Rescue Rider Ormoc Chapter, a City-accredited CSO whose members are "CDRRMO accredited community disaster volunteers"; under the MOA the CSO augments HEMS and the CDRRMO (incl. mass casualty) and post-disaster operations, the CDRRMO trains and supplies them, HEMS supervises them in operations and the City is accountable for volunteer injury or loss. The CSO sits on the CDRRMC (EO 2024-032A) and the El Nino Task Force (EO 2023-0042). The MOA copy in the set is unsigned and not notarised. CDP PPAs 2.7.1-2.7.3 plan the ACDV roster, insurance premiums and training. [Imported at "approved and in use" from the assessor''s score. Attach the document and proof of use, or lower the strength, at validation.]'),
('37dc8c6f-efb6-5fff-a340-b1676a4db85d'::uuid, '4ea14592-7a60-5788-adad-55ccc1d630c5'::uuid, 'document', 'approved_in_use'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(issuances 2021-2024, read 6 Nov 2026) CDRRMC Res. 03/04 s.2022 adopt NDRRMC MC 64 s.2021 (ACDV accreditation, mobilisation, protection) and an insurance risk categorisation. [Imported at "approved and in use" from the assessor''s score. Attach the document and proof of use, or lower the strength, at validation.]'),
('cf9a91e5-a233-5b02-a4cb-771c32c27cbb'::uuid, 'a3561a08-069e-5542-9ffd-0d7ca99b62e6'::uuid, 'document', 'approved_in_use'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(doc review 6 Nov 2026) SP Res. 2023-112 (adopted 24 Apr 2023) sighted: the SP adopts the Ormoc City DRRM Ten-Year Plan 2023-2032 on the Mayor''s endorsement of 20 Feb 2023, after CDRRMC Res. No. 01 s.2023 (17 Feb 2023). EO 2024-032A Sec. 2(a) tasks the CDRRMC to approve, monitor, evaluate and regularly review and test the LDRRMP. [Imported at "approved and in use" from the assessor''s score. Attach the document and proof of use, or lower the strength, at validation.]'),
('aca3f959-98c9-5766-8a8b-efbf5af92859'::uuid, '4802802d-6669-51ed-a1ae-51b54830b004'::uuid, 'document', 'partial'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(doc review 6 Nov 2026) CDP 2024-2030 Vol. 2 Sec. C.1 (CCA-DRRM sub-sector, pp.197-213) sets goals, objectives and 5 programmes and names the CDRA database as "basis for all development planning"; LCCAP 2019-2030 is built on a CDRA (HLURB method) with RCP 8.5 projections, a GHG inventory and decision areas, and lists the LCCAP as CDP project no. 22. Weaknesses: the CDP still targets "110 barangays", the LCCAP predates the 2023 CDRA and the 10-Year Plan, and no LCCAP-LDRRMP crosswalk exists.'),
('ffa2e22e-8243-56af-83a9-d222ba720dd0'::uuid, '4802802d-6669-51ed-a1ae-51b54830b004'::uuid, 'document', 'partial'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(issuances 2021-2024, read 6 Nov 2026) The Flood Control and Drainage Improvement Master Plan and Feasibility Study was funded by CDRRMC Res. 03 s.2023 (18 May 2023, PHP 3.60 M from the CCTV line of the 5% LDRRMF 2023), Res. 04 s.2023 (May 2023, PHP 3.11 M reverted continuing capital outlay 2017-2022) and Res. 07 s.2023 (12 Dec 2023, a further PHP 4.31 M of unobligated 2023 balances). No contract, inception report or finished study was sighted, and the CDP still lists the drainage master plan as planned (PPA 2.12).'),
('ea8878b6-4045-5e56-9c84-027d7ee5ebc8'::uuid, '4e61821a-2091-527b-9fc9-a1999f4a6b6d'::uuid, 'document', 'approved_in_use'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(doc review 6 Nov 2026) CDP 2024-2030 PPA 2.4 (city and barangay contingency plans) and 2.21 (El Nino programme); EO 2023-0042 (19 May 2023) creates the El Nino Task Force and tasks it to formulate a preparedness and rehabilitation plan, which was not in the set. [Imported at "approved and in use" from the assessor''s score. Attach the document and proof of use, or lower the strength, at validation.]'),
('4ba1fe89-bbb3-58eb-a07e-7a79b9bdbc90'::uuid, '4e61821a-2091-527b-9fc9-a1999f4a6b6d'::uuid, 'document', 'approved_in_use'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(issuances 2021-2024, read 6 Nov 2026) CDRRMC Res. 2-A s.2021 adopted the Enhanced Contingency Plan for flood-affected barangays ("Oplan Lunop") and Res. 2-B s.2021 the Enhanced CP for Earthquake 2020-2025, both with COVID-19 protocols (3 May 2021), and sent them to the SP for approval. SP approval not sighted. The earthquake CP''s period ended in 2025, so it is due for update. [Imported at "approved and in use" from the assessor''s score. Attach the document and proof of use, or lower the strength, at validation.]'),
('23d734f6-447c-5dbe-a709-36a886c09172'::uuid, '80aca07c-2c0a-5c9b-8852-391f75e17315'::uuid, 'document', 'partial'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(doc review 6 Nov 2026) CDP 2024-2030 PPA 2.5 plans PSCP formulation and institutionalisation; no PSCP in the set.'),
('3a3f70ec-28d0-5a96-9d27-d15657f25561'::uuid, '62050213-3f6c-5c1b-ad96-ffc96cb10a76'::uuid, 'document', 'approved_in_use'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(doc review 6 Nov 2026) annual cycle shown: SP Res. 2024-088 (19 Mar 2024) adopts CDRRMC Res. 3 s.2024 approving the Trust Fund-LDRRMF 2024 Budget Program and Investment Plan (PHP 79,512,680.20) after CPDO/Budget/Accountant review; CDRRMC Res. 01 s.2025 approves the LDRRMIP Trust Fund CY2025 (PHP 52,713,712.18); Res. 05 s.2025 (30 Sep 2025) approves the 5% LDRRMF CY2026 Budget Program and Investment Plan (PHP 139,955,741.40); Res. 07 s.2025 endorses a supplemental PHP 493,550.11 and Res. 08 s.2025 reallocates PHP 2.0 M of the 2025 Trust Fund to drainage in Brgy South. SP approval of the CY2026 plan was not in the set. Res. 05 calls the plan CY2026 but its body cites the 2025 NTA and "LDRRMF CY 2025". No AA line. [Imported at "approved and in use" from the assessor''s score. Attach the document and proof of use, or lower the strength, at validation.]'),
('b88d1459-8770-51b8-8b59-67f32b44fc20'::uuid, '32ad7cea-17c7-50c7-b639-631673e3aba0'::uuid, 'observation', 'partial'::public.evidence_strength, 'Site observation, October 2026', 'Assessment team site visit', '(Oct 2026 site visit) Brgy. Liloan, a flood-prone barangay, has an established evacuation site, evacuation protocol, and camp coordination and management arrangements. One barangay does not yet show city-wide coverage (46 critical flood barangays), so the score stays 2.'),
('7ad790a6-1e4f-5c78-a90b-cc079a90fc54'::uuid, 'e327b421-ea9c-5038-9f7f-9357f6b96c0f'::uuid, 'document', 'approved_in_use'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(doc review 6 Nov 2026) EO 2023-0085 (29 Dec 2023) creates the Barangay DRRM Plan Review Team (CDRRMO Head as team leader, CPDO assistant team leader; CSWD, CHD-HEMS, IPGDO, ENRO, Liga, two CSOs; DILG CLGOO oversight). It adopts the Enhanced QAS for BDRRMP/C (NDRRMC MC 03 s.2022), checks barangay PAPs against hazards and the barangay AIP, issues a Certificate of Review and copies DILG within 3 days. No Certificates of Review or status matrix were in the set. [Imported at "approved and in use" from the assessor''s score. Attach the document and proof of use, or lower the strength, at validation.]'),
('3b1fc4a9-79f4-5233-bee1-f6e68e87ceb6'::uuid, 'e1800441-4564-5a86-9813-92c3d72de086'::uuid, 'document', 'approved_in_use'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(doc review 6 Nov 2026) CDRRMC Res. 05 s.2025 sets the CY2026 LDRRMF at PHP 139,955,741.40, stated as 5% "based on the total National Tax Allotment of the City"; Res. 03 s.2025 and SP Res. 2024-088 cite RA 10121 Sec. 21 / IRR Rule 18. [Imported at "approved and in use" from the assessor''s score. Attach the document and proof of use, or lower the strength, at validation.]'),
('8ea118a8-c29c-59af-a7e5-600c69a1f4d2'::uuid, '51b90def-3147-54ab-a71a-97b0e033d117'::uuid, 'document', 'approved_in_use'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(doc review 6 Nov 2026) CDRRMC Res. 05 s.2025 allocates PHP 97,969,018.98 (70%) to prevention-mitigation, preparedness, response and recovery and PHP 41,986,722.42 (30%) to the QRF; Res. 07 s.2025 splits a supplemental share 30/70 (QRF PHP 148,065.03; mitigation and preparedness PHP 345,485.08). [Imported at "approved and in use" from the assessor''s score. Attach the document and proof of use, or lower the strength, at validation.]'),
('3566b5ff-cb76-5eca-927e-4f45550d7c74'::uuid, 'cbee3855-118c-52f2-8301-83cd669c6703'::uuid, 'document', 'approved_in_use'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(doc review 6 Nov 2026) SP Res. 2024-088 adopts the Trust Fund-LDRRMF 2024 plan (PHP 79,512,680.20) and cites RA 10121 Sec. 21 (5-year use) and COA Circular 2012-002 Sec. 4.4; CDRRMC Res. 01 s.2025 approves the CY2025 Trust Fund plan (PHP 52,713,712.18); Res. 08 s.2025 reallocates PHP 2.0 M of it to a drainage project after City Accountant advice that CDRRMC approval and SP concurrence are needed. [Imported at "approved and in use" from the assessor''s score. Attach the document and proof of use, or lower the strength, at validation.]'),
('1074b26d-2524-5ef7-9f0c-7c1c6bbf7d8c'::uuid, '2e056aca-2637-522c-91b6-069aa6e1a801'::uuid, 'document', 'partial'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '10-Yr Plan SWOC notes QRF utilisation/accessibility is a challenge.'),
('f6ed7a32-efff-5eea-a319-9fc3226f71b5'::uuid, '2e056aca-2637-522c-91b6-069aa6e1a801'::uuid, 'document', 'partial'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(doc review 6 Nov 2026) Trust Fund balances of PHP 79.5 M (2024 plan) and PHP 52.7 M (CY2025 plan) show sizeable unexpended LDRRMF carried forward; Res. 06 s.2025 draws PHP 2.0 M from the QRF for Typhoon Tino. No utilisation report was in the set.'),
('e3046d1a-9a57-567d-ace0-929112dd4a4d'::uuid, '88c9dbde-603a-5b23-a4cd-4882ef0fb4e6'::uuid, 'document', 'partial'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(doc review 6 Nov 2026) the CY2026 LDRRMF plan (Res. 05 s.2025, 30 Sep 2025) predates the IRR and has no AA line. CDP 2024-2030 PPA 3.15 "Risk and forecast-based Financing Support Program" and PPA 1.1.7 (FNFI prepositioning for imminent threat) give a programme hook for the AA line.'),
('72c573a4-51dd-5a67-9293-d6fd36b7690c'::uuid, '7114b994-82b1-5ed5-9135-499924a1cbc2'::uuid, 'document', 'approved_in_use'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(doc review 6 Nov 2026) CDP 2024-2030 PPAs 1.3 (Disaster Risk Financing Program, incl. insurance of equipment, buildings and vital assets) and 1.2.3 (insure EWS devices); LCCAP 2019-2030 activity 3 enlists all 4,540 registered farmers in crop insurance (10% then unregistered). [Imported at "approved and in use" from the assessor''s score. Attach the document and proof of use, or lower the strength, at validation.]'),
('c7a7b595-7447-51f4-8897-e2ff072fe9df'::uuid, 'cc6fb7f3-7e53-51af-9daa-122c2e3b7c51'::uuid, 'document', 'approved_in_use'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(doc review 6 Nov 2026) LCCAP 2019-2030 includes risk and susceptibility maps for flood, landslide, storm surge, earthquake, liquefaction and tsunami; the 2022 Ecological Profile (CDP Vol. 1) maps flood, landslide, ground shaking, liquefaction, rain-induced landslide and storm surge (SSA 1-4). Both predate the 85-barangay boundaries or use the old barangay base. [Imported at "approved and in use" from the assessor''s score. Attach the document and proof of use, or lower the strength, at validation.]'),
('f903b031-2189-516d-bbfe-bedf2edece7d'::uuid, '3c7cd8e5-365c-5250-9266-88d8a9d27ab6'::uuid, 'document', 'approved_in_use'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(doc review 6 Nov 2026) EO 2023-0025 (8 Mar 2023) creates the CDRA Technical Working Group (CPDO, CDRRMO, CSWD, Agriculture, ENRO, Engineering, CGSO, HEMS, Waterworks and 7 other offices, with DILG, DPWH, LEYECO V, NGCP, EDC, VSU and NRC as partners) to produce an updated CDRA and database, hazard and risk maps and to update them every 3-5 years. An earlier CDRA underpins the LCCAP 2019-2030 (TWG under EO No. 50 s.2017). [Imported at "approved and in use" from the assessor''s score. Attach the document and proof of use, or lower the strength, at validation.]'),
('1b261369-cc70-5a5e-8c5d-192684f6073e'::uuid, '96b50559-910e-5edd-a199-8c843d7301eb'::uuid, 'document', 'partial'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(doc review 6 Nov 2026) EO 2023-0025 Sec. 3(3)-(4) tasks the CDRA TWG to use GIS for geotagging and to produce updated hazard and risk maps; CDP PPA 1.15.6 plans a database and information management system. CDRRMO GIS staffing and software still to be confirmed.'),
('aca61bc9-91b5-512c-8f46-15cc0c5fc2d7'::uuid, '2b9e564b-b2b7-5759-a5a3-bfe6c66b5e39'::uuid, 'document', 'partial'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(doc review 6 Nov 2026) EO 2023-0025 Sec. 3(5) sets "continuous updating of the CDRA, databases, and maps every 3 to 5 years".'),
('3ff5c4c7-6dcf-5f6d-910e-14fe7feeb3d7'::uuid, '2137e00a-8b2c-5fa2-919c-6564fa36fbb9'::uuid, 'document', 'approved_in_use'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(doc review 6 Nov 2026) CDP 2024-2030 PPA 1.2 "Ormoc City DRRM Operations Center Integrated Multi-hazard Early Warning System" (EWS installation, preventive maintenance, insurance, regular positions, NGA/academe partnerships, gender-sensitive and inclusive EWS SOP) and strategy 3 (digital EWS devices, CCTV); LCCAP project on climate monitoring stations with the CDRRMO. [Imported at "approved and in use" from the assessor''s score. Attach the document and proof of use, or lower the strength, at validation.]'),
('a16d4dcf-ce57-5d67-b003-a7183554c9bb'::uuid, '9ac83d4c-1e6f-57da-bce8-845b46b7796e'::uuid, 'document', 'partial'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(issuances 2021-2024, read 6 Nov 2026) 2021-2022 evacuation and suspension orders were each issued by a separate council resolution at the time of the event (Res. 08, 09 s.2021; 06 s.2022). This confirms the gap: actions are decided per event, not pre-set against warning levels.'),
('9892224a-96d7-50a2-8f91-2706090dfa73'::uuid, '37a945ad-cb5c-5880-9c28-fa9e629ec523'::uuid, 'document', 'partial'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(doc review 6 Nov 2026) CDP 2024-2030 PPA 2.1 plans inclusive, gender-sensitive IEC materials, a risk communications plan and a regular risk communications position.'),
('537a5205-4457-58c9-b62f-ad8d735667f3'::uuid, '38954d31-1f20-5a43-b8ab-2080a52c5dfd'::uuid, 'observation', 'partial'::public.evidence_strength, 'Site observation, October 2026', 'Assessment team site visit', '(Oct 2026 site visit) an established evacuation site, with camp coordination and management arrangements, was seen in Brgy. Liloan; a standards check (WASH, privacy, PWD access, RA 12076) was not part of the visit.'),
('db003702-1162-5ad4-a1c3-e94e9bfb8125'::uuid, '9dc1ffab-e2d5-5a17-aa0c-9b8337e7cd26'::uuid, 'document', 'approved_in_use'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(doc review 6 Nov 2026) CDRRMC Res. 06 s.2025 used PHP 2.0 M of the QRF to buy food and non-food items to augment CSWD relief for Typhoon Tino, which shows replenishment during an event; CDP PPAs 1.1.7 (FNFI for prepositioning on imminent threat) and 1.17 (updating of the stockpile inventory system). No inventory or replenishment trigger was in the set. [Imported at "approved and in use" from the assessor''s score. Attach the document and proof of use, or lower the strength, at validation.]'),
('d31a9932-ff13-5174-8001-8f77acf3d3fd'::uuid, '10e6af20-126c-54e6-9022-125426cc9fa0'::uuid, 'document', 'approved_in_use'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(doc review 6 Nov 2026) EO 2024-032A seats the IPGDO (gender and development) on the CDRRMC; CDP 2024-2030 PPAs 1.2.6 (gender-sensitive and inclusive EWS SOP), 2.1 (inclusive IEC and risk communications) and 2.20 (Comprehensive Emergency Program for Children). [Imported at "approved and in use" from the assessor''s score. Attach the document and proof of use, or lower the strength, at validation.]'),
('e61040de-ea96-5689-9f92-e6fe657dcba4'::uuid, 'd9d7806b-ffbb-567c-98c0-e7fb057f8a88'::uuid, 'document', 'approved_in_use'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(doc review 6 Nov 2026) CDRRMC Res. 04 s.2025 approves a MOA between the City and all tertiary institutions in Ormoc for an Education Resilience and DRRM Coordination Group; CDP PPA 2.16 trains school DRRM coordinators; DepEd SDO, PRC and DOH-CHD HEMS sit on the CDRRMC. [Imported at "approved and in use" from the assessor''s score. Attach the document and proof of use, or lower the strength, at validation.]'),
('d0f0ba48-75dd-5d35-87a0-fc315b774458'::uuid, 'f957b0fc-b812-5e34-9a27-342f30f56922'::uuid, 'document', 'partial'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(doc review 6 Nov 2026) CDRRMC Res. No. 09 s.2024 (29 Nov 2024) adopts the Incident Command System as the standard management system for planned and unplanned events in Ormoc and directs the CDRRMO to train city and barangay officials and responders, integrate ICS into plans, drills and simulations, and evaluate its use. No Mayor''s EO, IMT roster or pre-designated Incident Commanders in the set. CDP PPA 3.3 funds "EOC and ICS support".'),
('28fbbb31-2afd-5c11-9cfd-6aee00068c12'::uuid, '0fa90af3-ab44-5839-91be-b68ea704aad4'::uuid, 'document', 'approved_in_use'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(doc review 6 Nov 2026) CDP 2024-2030 Table 17 programme 3.0 sets response support programmes by function (EOC and ICS, emergency telecoms, logistics, MDM, SRR, CCCM, education, FNFI, health, temporary resettlement, lifelines), matching the cluster approach; cluster lead offices sit on the CDRRMC (EO 2024-032A). [Imported at "approved and in use" from the assessor''s score. Attach the document and proof of use, or lower the strength, at validation.]'),
('3aba048a-ad36-530c-a53b-0ec422e31162'::uuid, '0fa90af3-ab44-5839-91be-b68ea704aad4'::uuid, 'document', 'approved_in_use'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(issuances 2021-2024, read 6 Nov 2026) EO s.2022 (filed as EO 263; the scan reads "243", check the number) organises the City CCCM Team under the CDRRMC Response Cluster, led by the CSWDO, with CDRRMO, CHD, Police, Engineering, GSO, Housing, Legal, DepEd, Liga, Red Cross, an NGO and a civic group; its functions cover EC availability, temporary refuge, basic needs, 24/7 health services, animal areas and transition to recovery. [Imported at "approved and in use" from the assessor''s score. Attach the document and proof of use, or lower the strength, at validation.]'),
('3c59a565-04aa-5048-9de0-a2bfa7e198df'::uuid, '0fa90af3-ab44-5839-91be-b68ea704aad4'::uuid, 'observation', 'approved_in_use'::public.evidence_strength, 'Site observation, October 2026', 'Assessment team site visit', '(Oct 2026 site visit) camp coordination and management arrangements were observed at the evacuation site in Brgy. Liloan. [Imported at "approved and in use" from the assessor''s score. Attach the document and proof of use, or lower the strength, at validation.]'),
('8ba25822-5957-52f0-a302-789c83be3b60'::uuid, '8a64d65d-181f-5c3a-af70-ee88f8850e6f'::uuid, 'document', 'partial'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(doc review 6 Nov 2026) CDP PPAs 3.6 (MDM response support) and 4.2 (PDNA capacity building and conduct) are planned; no team designation in the set.'),
('67b236ad-4c66-58a7-a367-cc923ce24932'::uuid, '8a64d65d-181f-5c3a-af70-ee88f8850e6f'::uuid, 'document', 'partial'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(issuances 2021-2024, read 6 Nov 2026) CDRRMC Res. 06 s.2021 (29 Sep 2021) approved the MDM Cluster protocol for deaths from COVID-19; Allotment Release Order 381 (2021) released MOOE for disease control and MDM operations. Score 1 -> 2: an approved, used MDM protocol exists, but it covers COVID-19 only; no all-hazards MDM team or RDANA team is designated.'),
('af771f69-a720-5719-9a78-1bce4870f68b'::uuid, '4fa4d322-826b-56f4-b035-bb48d48d24e2'::uuid, 'document', 'partial'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(doc review 6 Nov 2026) CDP 2024-2030 PPA 4.1 plans a TWG for the Disaster Rehabilitation and Recovery Plan, PlanSmart Ready to Rebuild training and formulation and updating of the DRRP; no TWG order in the set.'),
('40bdc56a-be87-5cdc-988c-c565ad6fe439'::uuid, '5b252962-c5ba-5b3c-a5a8-a493b600a9a0'::uuid, 'document', 'partial'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(issuances 2021-2024, read 6 Nov 2026) after Typhoon Odette (Dec 2021) the City sent cash aid to other LGUs: CDRRMC Res. 12, 14 and 15 s.2021 and SP Res. 2021-365, -367 and -369 (to five Southern Leyte LGUs, to Cebu City and the Province of Cebu, and to five Leyte LGUs; SP 2021-365 authorises PHP 11.24 M from the 2021 Quick Response Fund, including PHP 1 M each to the five Southern Leyte LGUs), and SP Res. 2021-368 donated rice. This shows willingness to help neighbours but no standing reciprocal agreement, so the score stays 1.'),
('100cd0c6-6fbc-5864-bc9b-3c522de9dd0b'::uuid, '7ee40260-e492-57cb-bc61-911289ee9ea8'::uuid, 'document', 'approved_in_use'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(doc review 6 Nov 2026) partnerships documented and approved: SP Res. 2023-347 and MOA with CPR-RIMT Rapid Rescue Rider Ormoc Chapter (volunteer augmentation); CDRRMC Res. 04 s.2025 MOA with all tertiary institutions (Education Resilience and DRRM Coordination Group); EO 2023-0026 Project TRANSFORM TWG with DENR, EDC and NRC under the Adopt-a-City Program; EDC, LEYECO V and 5 CSOs on the CDRRMC (EO 2024-032A); CPR-RIMT and two farmer cooperatives on the El Nino Task Force (EO 2023-0042). [Imported at "approved and in use" from the assessor''s score. Attach the document and proof of use, or lower the strength, at validation.]'),
('0357be1d-5c98-5eb2-98b5-0f824f11ea30'::uuid, '7ee40260-e492-57cb-bc61-911289ee9ea8'::uuid, 'document', 'approved_in_use'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(issuances 2021-2024, read 6 Nov 2026) SP Res. 2021-036 (18 Jan 2021) authorised the MOA among the City, the National Resilience Council, the Carlos P. Romulo Foundation and EDC; SP Res. 2021-357 (Dec 2021) authorised an MOU with the Oscar M. Lopez Center on climate and geo-hazard research and training. [Imported at "approved and in use" from the assessor''s score. Attach the document and proof of use, or lower the strength, at validation.]'),
('e0f3ceb5-6be7-5189-825e-a898b66b62d1'::uuid, 'b0dde175-d7f2-5cca-a7ff-bf06c2aac1cb'::uuid, 'document', 'partial'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(doc review 6 Nov 2026) EO 2024-032A Sec. 2(a) tasks the CDRRMC to monitor and evaluate the LDRRMP; EO 2023-0026 tasks the Project TRANSFORM TWG to monitor indicators in the NRC resilience scorecard; CDP Vol. 2 sets vision success indicators for DRRM (e.g., share of budget to DRRM, Gawad KALASAG, BLS-trained ratio, barangay functionality). No annual M&E report in the set.'),
('9ab2ffa2-45c7-5aa3-b186-b9b256f62c19'::uuid, 'b0dde175-d7f2-5cca-a7ff-bf06c2aac1cb'::uuid, 'document', 'partial'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(issuances 2021-2024, read 6 Nov 2026) EO 2022-00020 created the CDRRMP Technical Working Group for formulation, implementation, monitoring and evaluation of the City DRRM Plan, with thematic focal offices (ENRO prevention-mitigation, DILG preparedness, CSWDO response, CPDO recovery).'),
('c0de66ed-35b8-5b18-a52a-346cb8f88b56'::uuid, '5be8e243-5d21-5eeb-a3c6-865733405b24'::uuid, 'document', 'approved_in_use'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(doc review 6 Nov 2026) CDP 2024-2030 C.1 goal 3 "Ensure the achievement of Gawad Kalasag Award yearly" and objective 8 (100% compliance with SGLG disaster indicators). [Imported at "approved and in use" from the assessor''s score. Attach the document and proof of use, or lower the strength, at validation.]'),
('1854184c-64f8-50e3-aa4c-5a2630882ffc'::uuid, 'cc061ec2-0145-591c-9cca-6d70c4a9e58f'::uuid, 'document', 'partial'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(doc review 6 Nov 2026) EO 2023-0026 records Ormoc as a signatory of the EDC-NRC Adopt-a-City MOA and the model LGU for DENR-EDC Project TRANSFORM; CDP strategy 5 adopts the UNDRR Ten Essentials. Changes resulting from these networks are not documented.'),
('85b40b12-dc8f-5b54-a6a3-6700dc2de5d4'::uuid, 'cc061ec2-0145-591c-9cca-6d70c4a9e58f'::uuid, 'document', 'partial'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(issuances 2021-2024, read 6 Nov 2026) SP Res. 2021-036 (NRC-CPRF-EDC MOA, 2021) is the earlier basis of the NRC Resilient LGU partnership.'),
('eb5b59f6-cdf9-58a7-ba20-d42bb71a74ca'::uuid, '67a69792-0f29-54e6-b586-e5c9de268741'::uuid, 'document', 'partial'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(doc review 6 Nov 2026) none of the 23 City issuances creates the EOC. EO 2024-032A (CDRRMC) does not mention the EOC or OpCen. CDP 2024-2030 has two separate programmes: 2.10 "Ormoc City DRRM Operations Center" (construction/repair, integrated operating systems, OpCen SOP/Manual) and 3.3 "Emergency Operations Center and Incident Command System Support".'),
('6b139346-2ee0-5978-8584-1ac3d05937ea'::uuid, '67a69792-0f29-54e6-b586-e5c9de268741'::uuid, 'observation', 'partial'::public.evidence_strength, 'Site observation, October 2026', 'Assessment team site visit', '(Oct 2026 site visit) a developing EOC is co-located with the OpCen in the CDRRM Office and runs 24-hour duty for City Traffic Monitoring, Public Safety and Emergency Monitoring. This is an integrated operations-centre model (CDP strategy 2). No EO creating the EOC was found in the 2021-2024 issuances either.'),
('b75adc6f-16c4-5e2c-9e19-da25cb82256e'::uuid, '962ee543-8c2e-5526-b7fb-545f03d184f1'::uuid, 'document', 'approved_in_use'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', 'activation SOP (field note) and RDRRMC8 Res. 12-006 define White/Blue/Red; Blue = at least 50% of resources ready. RDRRMOC SOPG 2022 (OCD VIII) sets White, Blue and Red alerts with raising and downgrading rules for the regional OpCen. [Imported at "approved and in use" from the assessor''s score. Attach the document and proof of use, or lower the strength, at validation.]'),
('b0945b6a-52fa-51c7-87b1-1622ff3a9d5a'::uuid, '40ceca04-5ca2-5e21-91f5-820d960a5a59'::uuid, 'document', 'partial'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '10-Yr Plan says EOC operations need institutionalising through a manual/SOP. | Manual Development is on going'),
('24120411-85f1-5712-95d2-87abcbc8ba14'::uuid, '21222890-22c7-5521-a159-2b30898d676e'::uuid, 'observation', 'approved_in_use'::public.evidence_strength, 'Site observation, October 2026', 'Assessment team site visit', '(Oct 2026 site visit) the EOC site was geospatially validated using KML coordinates and cross-referenced with official hazard maps. The facility is outside high-risk flood, landslide, tsunami and liquefaction zones, which meets recommended site-selection criteria for emergency operations facilities. The site is not named in the 10-Yr Plan, CLUP or CDRA. [Imported at "approved and in use" from the assessor''s score. Attach the document and proof of use, or lower the strength, at validation.]'),
('4428487f-3d4f-5569-8af7-d95898210ed7'::uuid, '36bed9fd-238f-5c18-8e2a-ec505837bf6e'::uuid, 'observation', 'approved_in_use'::public.evidence_strength, 'Site observation, October 2026', 'Assessment team site visit', '(Oct 2026 site visit) the lead assessor sighted a structural assessment or occupancy permit for the EOC building. The 10-Yr Plan records city hall retrofitting (2016-2020); the ZO sets a 5-m easement on the Marina Fault trace. [Imported at "approved and in use" from the assessor''s score. Attach the document and proof of use, or lower the strength, at validation.]'),
('8f625519-31f3-511d-a01b-1ecc36d97d33'::uuid, '9f5775db-53b3-5711-8805-8f5ba837f7cf'::uuid, 'observation', 'approved_in_use'::public.evidence_strength, 'Site observation, October 2026', 'Assessment team site visit', '(Oct 2026 site visit) the lead assessor sighted generator or UPS capacity, a test log or a 72-hour fuel stock record. The 10-Yr Plan OpCen Program funds fuel and maintenance. [Imported at "approved and in use" from the assessor''s score. Attach the document and proof of use, or lower the strength, at validation.]'),
('b41b6a2f-8d02-5d4d-8779-778e56f0d7b7'::uuid, '9f5775db-53b3-5711-8805-8f5ba837f7cf'::uuid, 'document', 'approved_in_use'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(issuances 2021-2024, read 6 Nov 2026) CDRRMC Res. 10 s.2021 (15 Dec 2021) asked LEYECO V to run its 2 MW standby generator at Brgy. Alta Vista during widespread outages. [Imported at "approved and in use" from the assessor''s score. Attach the document and proof of use, or lower the strength, at validation.]'),
('fd7698a0-6f36-5d59-817c-015873ddeec6'::uuid, '4f32ceb3-ecb8-504e-86ad-b7ce5cc23e0a'::uuid, 'observation', 'approved_in_use'::public.evidence_strength, 'Site observation, October 2026', 'Assessment team site visit', '(Oct 2026 site visit) floor plan or room list sighted; the EOC shares the CDRRM Office with the OpCen. The 10-Yr Plan describes a fully functional 24/7 EOC. [Imported at "approved and in use" from the assessor''s score. Attach the document and proof of use, or lower the strength, at validation.]'),
('0bd91851-85e7-59d3-a8cc-a4a022108945'::uuid, 'b71cc677-72e7-52e9-91e5-f679d8c8055c'::uuid, 'document', 'approved_in_use'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', 'CCTV in the 10-Yr Plan is for hazard monitoring (OpCen integrated EWS); no EOC access-control rule, ID system or visitor log sighted. [Imported at "approved and in use" from the assessor''s score. Attach the document and proof of use, or lower the strength, at validation.]'),
('d9fb3c06-e324-5a48-a93a-a45f08f0759b'::uuid, 'd2ae6ad4-75bf-5d44-908e-873837d4dacb'::uuid, 'document', 'approved_in_use'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '10-Yr Plan plans the Leyte DRRMCs Telecom and Response Network. [Imported at "approved and in use" from the assessor''s score. Attach the document and proof of use, or lower the strength, at validation.]'),
('c146c07d-1b19-57e2-8683-04f1cfa80ff6'::uuid, 'a230adb8-4ecd-5529-925b-217ac6ab5ea4'::uuid, 'observation', 'partial'::public.evidence_strength, 'Site observation, October 2026', 'Assessment team site visit', '(Oct 2026 site visit) 24-hour duty observed for the three monitoring streams; the roster and handover record were not sighted, so the score stays 2.'),
('9b438814-4f70-50c4-9ab5-b41727867bbe'::uuid, '1fe91271-0036-5004-8551-65fc8070bbcc'::uuid, 'document', 'partial'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(doc review 6 Nov 2026) CDRRMC Res. 09 s.2024 adopts ICS but does not define how the EOC supports the Incident Commander; the CPR-RIMT MOA (SP Res. 2023-347) places volunteers under HEMS supervision during emergencies, a separate line from the EOC/IMT.'),
('5380d0c2-2698-5af4-b934-2709022bbac3'::uuid, '51012494-7f0c-58e7-95a1-1108515544f2'::uuid, 'document', 'partial'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(doc review 6 Nov 2026) SP Res. 2024-102 (2 Apr 2024; file named "SP RESOLUTION NO. 2024-1027") grants the Mayor or OIC Mayor omnibus authority to accept donations of perishable goods and goods given during or after calamities and to sign deeds of donation. Volunteers: CPR-RIMT MOA (SP Res. 2023-347). No donations-handling SOP in the set.'),
('c0986600-f9df-59c7-af24-c7f538a3a22a'::uuid, 'f27754e4-1e4a-5073-8a60-ad336eb3f297'::uuid, 'document', 'approved_in_use'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(doc review 6 Nov 2026) CDP 2024-2030 PPAs 2.10.1-2.10.4 (OpCen construction/repair, integrated operating systems, SOP/Manual, support services) and 3.3.1 (support services for EOC and ICS operations). [Imported at "approved and in use" from the assessor''s score. Attach the document and proof of use, or lower the strength, at validation.]'),
('5534b286-c7a1-5131-bd28-35de74e7c866'::uuid, 'ff9acfdf-8a70-5f66-a587-b852fbb9b715'::uuid, 'document', 'partial'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(doc review 6 Nov 2026) LCCAP 2019-2030 decision areas set high-risk barangays and values (29 barangays, 445.17 ha, PHP 13.36 B flood risk; 16 barangays, 297.6 ha of farmland) and name the Pagsangaan River as the key flood-control project; CDP 2024-2030 makes the CDRA database the basis for development planning (strategy 4). Neither defines most-probable and most-severe scenarios.'),
('e00d8fa2-b821-5778-94de-134469d155cf'::uuid, 'e8ab7e23-6b6f-54e5-9ce3-11546011ebea'::uuid, 'document', 'partial'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(doc review 6 Nov 2026) LCCAP 2019-2030 names livelihood exposure (8,000 informal-economy workers, 1,686 fisherfolk, 4,540 farmers) and agricultural values at risk (PHP 13.16 M), and cites TY Yolanda agricultural damage (PHP 2.059 B) and the 2015-16 El Nino damage; jobs and income losses are still not quantified.'),
('855199a1-32e6-5508-8888-9ee175127f31'::uuid, '1ccc93c6-a8b5-5701-9c55-497a0687abc6'::uuid, 'document', 'partial'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(doc review 6 Nov 2026) CDP 2024-2030 PPA 1.6 plans structural integrity assessment, infrastructure audit and an inventory of critical infrastructure (with regular positions); none done in the set.'),
('41ce465e-7da7-5cf3-8b5a-264f32aec841'::uuid, 'cd3c087e-ac5b-5aa6-bf83-eee0121a92a4'::uuid, 'document', 'partial'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(doc review 6 Nov 2026) LEYECO V sits on the CDRRMC (EO 2024-032A); LEYECO V and NGCP Milagro are CDRA TWG partners (EO 2023-0025); CDP PPA 3.16 plans restoration of critical lifelines. No restoration-priority agreement sighted.'),
('02a1d552-d8ad-5859-9d63-7cceef35de10'::uuid, 'cd3c087e-ac5b-5aa6-bf83-eee0121a92a4'::uuid, 'document', 'partial'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(issuances 2021-2024, read 6 Nov 2026) CDRRMC Res. 10 s.2021 (Odette) asked LEYECO V to use its 2 MW standby generator at Brgy. Alta Vista during widespread outages. Score 1 -> 2: one documented power arrangement used in an event; none for water or telecom, and no standing restoration-priority list.'),
('cf006232-d2d6-580f-9eb7-3e906666073c'::uuid, '31ccda55-5294-5294-bdf3-daa5fc4f1e84'::uuid, 'document', 'partial'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(doc review 6 Nov 2026) LCCAP 2019-2030 sets coastal (mangrove forest beach, 50 ha in San Antonio, Macabug, Naungan) and forest ecosystem decision areas and a biodiversity assessment; EO 2023-0026 Project TRANSFORM covers biodiversity profiling and nature-based solutions.'),
('393d770b-63d7-519e-a6ef-b22da6264ee3'::uuid, 'b7abd85d-a44b-5e48-8305-6e4e2cb57d52'::uuid, 'document', 'partial'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(doc review 6 Nov 2026) CDRRMC Res. 08 s.2025 reallocates PHP 2.0 M of the 2025 Trust Fund to drainage works on Malacadios St., Brgy South (flood mitigation); LCCAP lists slope protection on Milagro-Danao roads (CDRRMO, Engineering, barangays) and Pagsangaan River bank stabilisation; CDP PPA 2.12 plans the Drainage and Sewerage Master Plan. These are mitigation works, not pre-impact anticipatory actions.'),
('541f3e58-c300-5982-8986-6765f4d133cf'::uuid, 'b7abd85d-a44b-5e48-8305-6e4e2cb57d52'::uuid, 'document', 'partial'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(issuances 2021-2024, read 6 Nov 2026) the flood-control and drainage master plan and feasibility study was funded in 2023 (CDRRMC Res. 03, 04 and 07 s.2023, about PHP 11.0 M in total); no output was sighted. Still mitigation, not pre-impact anticipatory action.'),
('1e2606d3-6695-53c1-bd93-dbe7ba909ba3'::uuid, 'e9779a68-4888-59ba-9576-f3bbd3e1344e'::uuid, 'document', 'partial'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(doc review 6 Nov 2026) CDP 2024-2030 PPA 2.15 plans HEMS and Epidemiological Surveillance Unit institutionalisation and a contingency plan for emerging infectious disease; DOH-CHD HEMS and the CHO sit on the CDRRMC; HEMS supervises CPR-RIMT volunteers (SP Res. 2023-347).'),
('f9bf090e-9543-553d-a6b9-a5b1a229cc97'::uuid, '8f86dd62-3f71-5976-bb5a-63abb9717e11'::uuid, 'document', 'partial'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(doc review 6 Nov 2026) DepEd SDO sits on the CDRRMC (EO 2024-032A) and moved CDRRMC Res. 04 s.2025 (tertiary-institution MOA); CDP PPA 2.16 trains school DRRM coordinators. No school AA plans sighted.'),
('f8eaa2d2-bddf-51af-8d66-ed70a2d4a8ca'::uuid, '9a85561d-7e4b-53a9-bab4-a8799238c305'::uuid, 'document', 'partial'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(doc review 6 Nov 2026) EO 2023-0042 (19 May 2023) creates the El Nino Task Force chaired by the Mayor, with the City Agriculturist, CSWD, CDRRMO, CPDO, CHO, Engineering, two irrigators'' cooperatives and others, to formulate an El Nino preparedness and rehabilitation plan, monitor it and run an information campaign; LCCAP 2019-2030 plans crop insurance enrolment, climate-ready crop varieties and buffer-stock facilities; CDP PPAs 2.17 (climate-smart agriculture) and 2.21 (El Nino programme).'),
('fd912bf6-1c54-5fd3-81a6-5d4c289c2b9f'::uuid, '65eaff76-960d-5c38-9ed9-a15cd45c5cd0'::uuid, 'document', 'partial'::public.evidence_strength, 'Desk review, October-November 2026', 'Consultant desk review', '(doc review 6 Nov 2026) CDP 2024-2030 PPA 2.18 plans BCP capacity building for barangays and MSMEs, a BCP template for MSMEs and incentives for MSMEs with a BCP; EDC and LEYECO V sit on the CDRRMC.')
on conflict (id) do nothing;

